'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var PINF = require( '@stdlib/constants-float32-pinf' );
var NINF = require( '@stdlib/constants-float32-ninf' );
var BIAS = require( '@stdlib/constants-float32-exponent-bias' );
var randu = require( '@stdlib/random-base-randu' );
var round = require( '@stdlib/math-base-special-round' );
var pow = require( '@stdlib/math-base-special-pow' );
var toFloat32 = require( '@stdlib/number-float64-base-to-float32' );
var bits = require( '@stdlib/number-float32-base-to-binary-string' );
var tryRequire = require( '@stdlib/utils-try-require' );


// VARIABLES //

var exponentf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( exponentf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof exponentf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a number', opts, function test( t ) {
	t.strictEqual( typeof exponentf( toFloat32( 3.14e30 ) ), 'number', 'returns expected value' );
	t.end();
});

tape( 'the function returns an integer corresponding to the unbiased exponent of a single-precision floating-point number', opts, function test( t ) {
	var expected;
	var actual;
	var sign;
	var frac;
	var exp;
	var x;
	var b;
	var i;

	for ( i = 0; i < 5e3; i++ ) {
		if ( randu() < 0.5 ) {
			sign = -1.0;
		} else {
			sign = 1.0;
		}
		frac = randu() * 10.0;
		exp = round( randu()*44.0 ) - 22;
		x = sign * frac * pow( 10.0, exp );
		x = toFloat32( x );

		b = bits( x );
		expected = parseInt( b.substring( 1, 9 ), 2 ) - BIAS;

		actual = exponentf( x );
		t.strictEqual( actual, expected, 'returns the unbiased exponent for ' + x );
	}
	t.end();
});

tape( 'the function returns the unbiased exponent for `+-0`', opts, function test( t ) {
	t.strictEqual( exponentf( 0.0 ), -BIAS, 'returns -127' );
	t.strictEqual( exponentf( -0.0 ), -BIAS, 'returns -127' );
	t.end();
});

tape( 'the function returns the unbiased exponent for `+infinity`', opts, function test( t ) {
	t.strictEqual( exponentf( PINF ), BIAS+1, 'returns 128' );
	t.end();
});

tape( 'the function returns the unbiased exponent for `-infinity`', opts, function test( t ) {
	t.strictEqual( exponentf( NINF ), BIAS+1, 'returns 128' );
	t.end();
});

tape( 'the function returns the unbiased exponent for `NaN`', opts, function test( t ) {
	t.strictEqual( exponentf( NaN ), BIAS+1, 'returns 128' );
	t.end();
});

tape( 'the function returns the unbiased exponent for subnormals', opts, function test( t ) {
	t.strictEqual( exponentf( toFloat32( 3.14e-42 ) ), -BIAS, 'returns -127' );
	t.end();
});","lineStart":1,"lineEnd":111,"totalLines":111,"truncated":false}},"title":"repos/pc-lib-3456/number-float32-base-exponent/test/test.native.js","time":{"start":1783263693500,"end":1783263693504}},"id":"prt_f32cc89800017WPrn7cWYKJTPw","sessionID":"ses_0cd33c4faffe59ZXLTa22GB5Bz","messageID":"msg_f32cc7bb5001I58nWu58u3F47e"}}

