'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var randu = require( '@stdlib/random-base-randu' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var toFloat32 = require( '@stdlib/number-float64-base-to-float32' );
var pkg = require( './../package.json' ).name;
var exponentf = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var x;
	var y;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		x = ( randu()*1.0e7 ) - 5.0e6;
		y = exponentf( toFloat32( x ) );
		if ( isnan( y ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( y ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":52,"totalLines":52,"truncated":false}},"title":"repos/pc-lib-3456/number-float32-base-exponent/benchmark/benchmark.js","time":{"start":1783263708627,"end":1783263708635}},"id":"prt_f32ccc4a9001Onblo2aG1nQeTy","sessionID":"ses_0cd33c4faffe59ZXLTa22GB5Bz","messageID":"msg_f32ccb514001B173kCNM6TBL6s"}}

